) VALUES
  (CONVERT(0x696E4C69624D7367436F6E66696775726163696F6E2E534465736372697063696F6E506172616D6574726F4964696F6D61 USING utf8mb4),
   'en-GB', CONVERT(0x496E74657266616365206C616E67756167653A2065732D45532C20656E2D47422C2063612D4553206F72207170732D706C6F6320666F722074657374696E67 USING utf8mb4),
   CONVERT(0x7372632F4C69622F696E4C69624D7367436F6E66696775726163696F6E2E706173 USING utf8mb4),
   'S', CURRENT_TIMESTAMP, 'D23')
ON DUPLICATE KEY UPDATE
  TEXTO_TRAD = VALUES(TEXTO_TRAD),
  INSTANTE_MODIF = CURRENT_TIMESTAMP,
  USUARIO_MODIF = VALUES(USUARIO_ALTA);
-- Comprobación: claves es-ES activas sin pareja ca-ES.
SELECT COUNT(*) AS PENDIENTES
  FROM fza_traducciones E
  LEFT JOIN fza_traducciones I
    ON I.CLAVE_TRAD = E.CLAVE_TRAD
   AND I.IDIOMA_TRAD = 'ca-ES'
   AND I.ESACTIVO_TRAD = 'S'
 WHERE E.IDIOMA_TRAD = 'es-ES'
   AND E.ESACTIVO_TRAD = 'S'
   AND I.ID_TRAD IS NULL;
